const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();

  // Load the page. We need to serve it or use a file URL.
  // Since it's a standalone HTML with absolute paths in the script, 
  // and it uses ESM imports from CDNs, setContent should work if we handle the relative CSS/JS.
  // Actually, app.js and style.css are in the same directory.

  const html = fs.readFileSync('index.html', 'utf8');
  await page.setContent(html, { waitUntil: 'networkidle' });

  // Inject axe-core
  await page.addScriptTag({ path: '/tmp/axe.min.js' });

  // Run axe
  const results = await page.evaluate(async () => {
    return await window.axe.run();
  });

  await browser.close();

  const wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
  const bp = results.violations.filter(v => v.tags.includes('best-practice'));

  console.log(JSON.stringify({
    wcag: wcag.map(v => ({ id: v.id, impact: v.impact, help: v.help, nodes: v.nodes.map(n => n.target) })),
    bp: bp.map(v => ({ id: v.id, impact: v.impact, help: v.help, nodes: v.nodes.map(n => n.target) }))
  }, null, 2));

  process.exit(wcag.length > 0 ? 1 : 0);
})();

