const fs = require('fs');
const path = require('path');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();

  // To avoid connection issues, let's use setContent but fix relative paths
  let html = fs.readFileSync('index.html', 'utf8');
  // Inject the CSS and JS content directly to bypass path issues in setContent
  const css = fs.readFileSync('style.css', 'utf8');
  const js = fs.readFileSync('app.js', 'utf8');

  html = html.replace('<link rel="stylesheet" href="style.css">', `<style>${css}</style>`);
  html = html.replace('<script type="module" src="app.js"></script>', `<script type="module">${js}</script>`);

  await page.setContent(html, { waitUntil: 'networkidle' });

  // Debug: Check if #app is populated
  const appContent = await page.innerHTML('#app');
  console.error('App content length:', appContent.trim().length);
  if (appContent.trim().length === 0) {
    console.error('Warning: #app is empty. Preact might not have rendered.');
  }
  await page.addScriptTag({ path: '/tmp/axe.min.js' });

  // Run axe
  const results = await page.evaluate(async () => {
    return await window.axe.run();
  });

  await browser.close();

  const wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
  const bp = results.violations.filter(v => v.tags.includes('best-practice'));

